insert into public.quest_templates (id, source, ability, difficulty, periods, title, flavor, objective, tips, validation, tags, theme, secondary, is_active) values
('for-easy-pompes-en-series-5-minutes', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Pompes en séries, 5 minutes', 'Les pompes travaillent pectoraux, épaules et triceps sans aucun matériel.', 'Pendant 5 minutes, enchaîner des séries de pompes (sur les genoux autorisé) avec un repos libre entre les séries.', array['Mieux vaut des séries propres que des répétitions bâclées.', 'Expire en poussant, inspire en descendant.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['sans matériel', 'moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('for-easy-squats-en-series-5-minutes', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Squats en séries, 5 minutes', 'Les cuisses et les fessiers sont les plus gros muscles du corps : on les sollicite en premier.', 'Pendant 5 minutes, enchaîner des séries de squats, dos droit et talons au sol.', array['Imagine que tu t’assois sur une chaise derrière toi.', 'Descends moins bas si tes genoux tirent.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['sans matériel', 'moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('for-easy-gainage-5-minutes-au-total', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Gainage, 5 minutes au total', 'Un tronc solide protège le dos et rend tous les autres efforts plus faciles.', 'Tenir des planches (face et côtés) pendant 5 minutes en tout, repos compris, en une ou plusieurs séries.', array['Coudes sous les épaules, corps aligné.', 'Fractionne en séries de 20 à 30 secondes si besoin.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['sans matériel', 'moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('for-easy-fentes-alternees-5-minutes', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Fentes alternées, 5 minutes', 'Les fentes renforcent chaque jambe séparément et corrigent les déséquilibres.', 'Pendant 5 minutes, enchaîner des fentes avant ou arrière en alternant les jambes.', array['Garde le buste droit et le genou avant au-dessus du pied.', 'Tiens-toi à un mur au début si tu perds l’équilibre.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['sans matériel', 'moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('for-easy-chaise-murale-3-minutes-cumulees', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Chaise murale, 3 minutes cumulées', 'Tenir une position statique fatigue les cuisses plus qu’on ne le croit.', 'Tenir la position de la chaise contre un mur pendant 3 minutes cumulées, en plusieurs fois si nécessaire.', array['Cuisses à l’horizontale, dos plaqué au mur.', 'Commence par des tenues de 20 secondes.']::text[], '{"type":"timer","minutes":3}'::jsonb, array['sans matériel', 'moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('for-easy-dips-sur-chaise-5-minutes', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Dips sur chaise, 5 minutes', 'Les triceps font la moitié du travail de poussée du haut du corps.', 'Pendant 5 minutes, enchaîner des séries de dips sur une chaise stable, repos libre entre les séries.', array['Cale la chaise contre un mur pour qu’elle ne glisse pas.', 'Garde les épaules loin des oreilles.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('for-easy-abdominaux-5-minutes', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Abdominaux, 5 minutes', 'Les abdominaux stabilisent le tronc dans presque tous les mouvements de force.', 'Pendant 5 minutes, alterner abdominaux, relevés de jambes et crunchs en séries courtes.', array['Mains près des tempes, sans tirer sur la nuque.', 'Souffle pendant l’effort.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['sans matériel', 'moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('for-easy-portage-avec-charge-5-minutes', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Portage avec charge, 5 minutes', 'Porter du poids sollicite tout le corps, comme dans la vraie vie.', 'Marcher pendant 5 minutes en portant une charge : sac chargé de livres, packs d’eau ou courses.', array['Garde le dos droit et la charge près du corps.', 'Change de main ou de côté à mi-parcours.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('for-easy-pont-fessier-5-minutes', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Pont fessier, 5 minutes', 'Des fessiers forts soulagent le bas du dos et stabilisent le bassin.', 'Pendant 5 minutes, enchaîner des séries de ponts fessiers, en marquant une pause d’une seconde en haut.', array['Pousse avec les talons, pas avec les orteils.', 'Passe sur une jambe quand c’est facile.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['sans matériel', 'moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('for-easy-poigne-et-avant-bras-5-minutes', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Poigne et avant-bras, 5 minutes', 'La poigne limite beaucoup d’exercices de tirage : c’est un point faible fréquent.', 'Pendant 5 minutes, travailler la poigne : serrer une balle, suspendre à une barre ou porter une charge à bout de bras.', array['Alterne les mains et laisse 30 secondes de repos entre les séries.', 'Une serviette roulée peut servir de balle.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('for-easy-circuit-corps-entier-10-minutes', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Circuit corps entier, 10 minutes', 'Un circuit court sollicite tous les groupes musculaires en peu de temps.', 'Pendant 10 minutes, enchaîner pompes, squats, gainage et fentes, un exercice après l’autre, sans pause longue.', array['Fais 30 secondes par exercice puis passe au suivant.', 'Reprends ton souffle entre les tours.']::text[], '{"type":"timer","minutes":10}'::jsonb, array['sans matériel', 'sport']::text[], null, '[]'::jsonb, true),
('for-easy-gainage-lateral-4-minutes-au-total', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Gainage latéral, 4 minutes au total', 'Les muscles latéraux du tronc protègent la colonne dans les efforts de portage.', 'Tenir le gainage latéral pendant 4 minutes cumulées, soit 2 minutes de chaque côté, en plusieurs séries.', array['Coude sous l’épaule, hanches hautes.', 'Séries de 15 à 30 secondes selon ta forme.']::text[], '{"type":"timer","minutes":4}'::jsonb, array['sans matériel', 'moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('for-easy-souleve-de-charge-10-minutes', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Soulevé de charge, 10 minutes', 'Savoir soulever correctement protège le dos pour tous les jours qui viennent.', 'Pendant 10 minutes, enchaîner des séries de soulevés de charge (sac lesté, bidon d’eau) en gardant le dos droit.', array['Fléchis les genoux, ne plie pas le dos.', 'Garde la charge collée contre toi.']::text[], '{"type":"timer","minutes":10}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-easy-tirage-et-rowing-5-minutes', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Tirage et rowing, 5 minutes', 'Le dos fait contrepoids à tout ce qu’on pousse : il se travaille aussi.', 'Pendant 5 minutes, enchaîner des séries de rowing avec un élastique, un sac chargé ou une table solide.', array['Tire les coudes vers l’arrière, pas les épaules vers les oreilles.', 'Contrôle la descente.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('for-medium-haut-du-corps-20-minutes', 'catalog', 'FOR', 'medium', array['daily', 'weekly']::text[], 'Haut du corps, 20 minutes', 'Une séance structurée progresse plus vite qu’une série isolée.', 'Pendant 20 minutes, enchaîner pompes, dips, rowing et gainage en séries de 8 à 15 répétitions.', array['Note le nombre de répétitions pour progresser la fois suivante.', 'Repos de 45 à 60 secondes entre les séries.']::text[], '{"type":"timer","minutes":20}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-medium-bas-du-corps-20-minutes', 'catalog', 'FOR', 'medium', array['daily', 'weekly']::text[], 'Bas du corps, 20 minutes', 'Un bas du corps solide aide à marcher, monter et se relever toute la vie.', 'Pendant 20 minutes, enchaîner squats, fentes, ponts fessiers et montées sur marche en séries de 10 à 15 répétitions.', array['Descends en contrôle, remonte avec force.', 'Garde les genoux dans l’axe des pieds.']::text[], '{"type":"timer","minutes":20}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-medium-renforcement-60-minutes-dans-la-semaine', 'catalog', 'FOR', 'medium', array['weekly']::text[], 'Renforcement, 60 minutes dans la semaine', 'Deux ou trois courtes séances par semaine suffisent à progresser en force.', 'Cumuler 60 minutes de renforcement musculaire sur la semaine, en plusieurs séances.', array['Répartis sur 2 ou 3 jours avec un jour de repos entre.', 'Ajoute les minutes après chaque séance.']::text[], '{"type":"counter","target":60,"unit":"minutes"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-medium-circuit-corps-entier-25-minutes', 'catalog', 'FOR', 'medium', array['daily']::text[], 'Circuit corps entier, 25 minutes', 'Un circuit complet fait travailler force et endurance musculaire à la fois.', 'Pendant 25 minutes, enchaîner un circuit de 6 exercices (pompes, squats, gainage, fentes, rowing, abdos) en plusieurs tours.', array['40 secondes d’effort, 20 secondes de repos.', 'Prépare l’ordre des exercices avant de commencer.']::text[], '{"type":"timer","minutes":25}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-medium-gainage-varie-10-minutes', 'catalog', 'FOR', 'medium', array['daily', 'weekly']::text[], 'Gainage varié, 10 minutes', 'Plusieurs variantes de gainage sollicitent tout le tronc, pas seulement le ventre.', 'Pendant 10 minutes, enchaîner planche, planche latérale et planche dos, en séries de 30 à 45 secondes.', array['Garde le corps aligné, sans cambrer.', 'Repose-toi dès que la forme se dégrade.']::text[], '{"type":"timer","minutes":10}'::jsonb, array['sans matériel', 'sport']::text[], null, '[]'::jsonb, true),
('for-medium-portage-de-charges-30-minutes', 'catalog', 'FOR', 'medium', array['weekly']::text[], 'Portage de charges, 30 minutes', 'Porter, c’est la force utile : courses, valises, enfants, déménagement.', 'Cumuler 30 minutes de portage sur la semaine : marche avec sac lesté, courses à pied ou charge à bout de bras.', array['Commence léger et ajoute du poids semaine après semaine.', 'Garde le dos droit.']::text[], '{"type":"counter","target":30,"unit":"minutes"}'::jsonb, array['extérieur', 'sport']::text[], null, '[]'::jsonb, true),
('for-medium-pompes-variees-15-minutes', 'catalog', 'FOR', 'medium', array['daily', 'weekly']::text[], 'Pompes variées, 15 minutes', 'Changer de variante de pompe travaille d’autres fibres et évite le plateau.', 'Pendant 15 minutes, alterner pompes classiques, serrées, surélevées et lentes en séries de 6 à 12.', array['Passe à la variante plus facile quand la forme baisse.', 'Descends en 3 secondes pour plus d’effet.']::text[], '{"type":"timer","minutes":15}'::jsonb, array['sans matériel', 'sport']::text[], null, '[]'::jsonb, true),
('for-medium-squats-lestes-15-minutes', 'catalog', 'FOR', 'medium', array['daily']::text[], 'Squats lestés, 15 minutes', 'Ajouter du poids est la façon la plus directe de gagner de la force.', 'Pendant 15 minutes, enchaîner des squats avec un sac à dos chargé ou un poids dans les bras.', array['Charge assez pour que 10 répétitions soient exigeantes.', 'Garde le sac collé au dos.']::text[], '{"type":"timer","minutes":15}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-medium-halteres-ou-elastiques-90-minutes', 'catalog', 'FOR', 'medium', array['weekly']::text[], 'Haltères ou élastiques, 90 minutes', 'Un travail avec charge, régulier, construit la force sur la durée.', 'Cumuler 90 minutes de travail avec haltères, élastiques ou machines sur la semaine.', array['Trois séances de 30 minutes font l’affaire.', 'Varie les groupes musculaires d’une séance à l’autre.']::text[], '{"type":"counter","target":90,"unit":"minutes"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-medium-seance-haut-et-bas-30-minutes', 'catalog', 'FOR', 'medium', array['daily', 'weekly']::text[], 'Séance haut et bas, 30 minutes', 'Une séance mixte progresse bien quand on manque de temps.', 'Pendant 30 minutes, alterner des exercices de haut du corps et de bas du corps, en séries de 8 à 12 répétitions.', array['Alterne pour reposer chaque groupe pendant que l’autre travaille.', 'Écris la séance à l’avance.']::text[], '{"type":"timer","minutes":30}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-medium-travail-de-tirage-40-minutes', 'catalog', 'FOR', 'medium', array['weekly']::text[], 'Travail de tirage, 40 minutes', 'Tractions, rowings et tirages équilibrent les muscles de la poussée et protègent les épaules.', 'Cumuler 40 minutes d’exercices de tirage sur la semaine : tractions, rowing, élastiques.', array['Une barre de porte ou une table solide suffit.', 'Aide-toi d’un élastique pour les tractions.']::text[], '{"type":"counter","target":40,"unit":"minutes"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-medium-seance-de-force-complete-30-minutes', 'catalog', 'FOR', 'medium', array['daily', 'weekly']::text[], 'Séance de force complète, 30 minutes', 'Une vraie séance de force, échauffement inclus, ancre l’habitude.', 'Faire une séance de force de 30 minutes : 5 minutes d’échauffement puis 25 minutes d’exercices variés.', array['Échauffe-toi avec du mouvement léger.', 'Termine par 2 minutes d’étirements.']::text[], '{"type":"timer","minutes":30}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-high-force-120-minutes-dans-la-semaine', 'catalog', 'FOR', 'high', array['weekly']::text[], 'Force, 120 minutes dans la semaine', 'Quatre séances de force par semaine font franchir un palier visible.', 'Cumuler 120 minutes de renforcement ou de musculation sur la semaine.', array['Prévois quatre créneaux de 30 minutes.', 'Garde un jour de repos complet.']::text[], '{"type":"counter","target":120,"unit":"minutes"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-high-pompes-et-dips-45-minutes', 'catalog', 'FOR', 'high', array['weekly']::text[], 'Pompes et dips, 45 minutes', 'Un volume régulier de poussée développe la force du haut du corps.', 'Cumuler 45 minutes de travail de poussée (pompes, dips, développés) sur la semaine.', array['Répartis sur 3 séances de 15 minutes.', 'Augmente d’une répétition à chaque séance.']::text[], '{"type":"counter","target":45,"unit":"minutes"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-high-seance-de-force-intense-45-minutes', 'catalog', 'FOR', 'high', array['daily', 'weekly']::text[], 'Séance de force intense, 45 minutes', 'Un format long permet de travailler plus de volume et de charge.', 'Pendant 45 minutes, faire une séance de force complète avec charge, échauffement et retour au calme inclus.', array['Planifie 5 exercices et 3 séries chacun.', 'Hydrate-toi pendant les repos.']::text[], '{"type":"timer","minutes":45}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-high-jambes-et-fessiers-60-minutes', 'catalog', 'FOR', 'high', array['weekly']::text[], 'Jambes et fessiers, 60 minutes', 'Le bas du corps est le plus gros réservoir de force du corps.', 'Cumuler 60 minutes de travail des jambes et des fessiers sur la semaine : squats, fentes, ponts, montées de marche.', array['Deux séances de 30 minutes.', 'Descends lentement, remonte avec puissance.']::text[], '{"type":"counter","target":60,"unit":"minutes"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-high-gainage-30-minutes-cumulees', 'catalog', 'FOR', 'high', array['weekly', 'monthly']::text[], 'Gainage, 30 minutes cumulées', 'Un gainage long et régulier sculpte un tronc stable et résistant.', 'Cumuler 30 minutes de gainage sur la période, en séries de 30 secondes à 2 minutes.', array['Note chaque série pour suivre ton total.', 'Varie face, côtés et dos.']::text[], '{"type":"counter","target":30,"unit":"minutes"}'::jsonb, array['sans matériel', 'sport']::text[], null, '[]'::jsonb, true),
('for-high-portage-lourd-45-minutes', 'catalog', 'FOR', 'high', array['weekly']::text[], 'Portage lourd, 45 minutes', 'Travailler la force fonctionnelle, c’est porter lourd, longtemps.', 'Cumuler 45 minutes de portage de charges lourdes sur la semaine : sacs, packs, bidons, valises.', array['Charge à 60 % de ce que tu peux porter.', 'Repose-toi dès que ton dos s’arrondit.']::text[], '{"type":"counter","target":45,"unit":"minutes"}'::jsonb, array['extérieur', 'sport']::text[], null, '[]'::jsonb, true),
('for-high-force-6-heures-dans-le-mois', 'catalog', 'FOR', 'high', array['monthly']::text[], 'Force, 6 heures dans le mois', 'Six heures de force par mois, c’est environ 90 minutes par semaine.', 'Cumuler 6 heures de renforcement musculaire sur le mois.', array['Planifie 3 séances par semaine.', 'Les minutes d’échauffement comptent.']::text[], '{"type":"counter","target":360,"unit":"minutes"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-high-poussee-et-tirage-4-heures', 'catalog', 'FOR', 'high', array['monthly']::text[], 'Poussée et tirage, 4 heures', 'Un bon équilibre entre pousser et tirer protège les épaules.', 'Cumuler 4 heures de travail de poussée et de tirage sur le mois, à parts à peu près égales.', array['Alterne les séances poussée et tirage.', 'Garde un cahier de répétitions.']::text[], '{"type":"counter","target":240,"unit":"minutes"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-high-corps-entier-5-heures-dans-le-mois', 'catalog', 'FOR', 'high', array['monthly']::text[], 'Corps entier, 5 heures dans le mois', 'Un volume mensuel régulier est ce qui change vraiment le corps.', 'Cumuler 5 heures de séances de force corps entier sur le mois.', array['Quatre séances par semaine de 20 minutes suffisent.', 'Mesure ta progression à la fin du mois.']::text[], '{"type":"counter","target":300,"unit":"minutes"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-expert-force-12-heures-dans-le-mois', 'catalog', 'FOR', 'expert', array['monthly']::text[], 'Force, 12 heures dans le mois', 'Douze heures de force par mois : un vrai engagement d’entraînement.', 'Cumuler 12 heures de renforcement musculaire sur le mois. Adapte à ta condition et consulte un professionnel au besoin.', array['Planifie tes séances dans ton agenda.', 'Garde au moins deux jours de repos par semaine.']::text[], '{"type":"counter","target":720,"unit":"minutes"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-expert-force-20-heures-de-travail', 'catalog', 'FOR', 'expert', array['monthly', 'epic']::text[], 'Force, 20 heures de travail', 'Vingt heures de force cumulées demandent de la constance sur la durée.', 'Cumuler 20 heures de renforcement musculaire en visant un objectif de progression mesurable. Adapte à ta condition.', array['Fixe un objectif précis (nombre de pompes, charge) au départ.', 'Mesure-toi au début et à la fin.']::text[], '{"type":"counter","target":1200,"unit":"minutes"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-expert-seances-de-force-5-heures', 'catalog', 'FOR', 'expert', array['weekly', 'monthly']::text[], 'Séances de force, 5 heures', 'Cinq heures de force dans la période demandent une vraie discipline.', 'Cumuler 5 heures de séances de force sur la période. Adapte à ta condition et à ton niveau de récupération.', array['Prévois des créneaux fixes.', 'Alterne les groupes musculaires.']::text[], '{"type":"counter","target":300,"unit":"minutes"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-expert-progression-de-force-25-heures', 'catalog', 'FOR', 'expert', array['monthly', 'epic']::text[], 'Progression de force, 25 heures', 'Un grand cycle de force, du premier jour à la mesure finale.', 'Suivre un cycle d’entraînement de force de 25 heures en tout, avec une mesure de départ et une mesure d’arrivée. Adapte à ta condition.', array['Teste-toi avant (pompes maximum, gainage maximum).', 'Programme plusieurs semaines pour récupérer correctement.']::text[], '{"type":"counter","target":1500,"unit":"minutes"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('for-expert-force-et-portage-15-heures', 'catalog', 'FOR', 'expert', array['monthly']::text[], 'Force et portage, 15 heures', 'Un mois de force utile : renforcement, portage et gainage.', 'Cumuler 15 heures de renforcement, portage de charges et gainage sur le mois. Adapte à ta condition.', array['Reste à l’écoute de tes articulations.', 'Alterne séances lourdes et séances légères.']::text[], '{"type":"counter","target":900,"unit":"minutes"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('dex-easy-etirements-complets-5-minutes', 'catalog', 'DEX', 'easy', array['daily']::text[], 'Étirements complets, 5 minutes', 'Un corps souple se blesse moins et bouge avec plus d’aisance.', 'Pendant 5 minutes, étirer successivement nuque, épaules, dos, hanches, cuisses et mollets, 30 secondes par zone.', array['Étire sans douleur : une tension douce suffit.', 'Respire lentement pendant chaque étirement.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['sans matériel', 'moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('dex-easy-equilibre-sur-une-jambe-5-minutes', 'catalog', 'DEX', 'easy', array['daily']::text[], 'Équilibre sur une jambe, 5 minutes', 'L’équilibre se travaille comme un muscle et protège contre les chutes.', 'Pendant 5 minutes, tenir en équilibre sur une jambe puis sur l’autre, en alternant, yeux ouverts puis yeux fermés.', array['Reste près d’un mur pour te rattraper.', 'Fixe un point devant toi pour tenir plus longtemps.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['sans matériel', 'moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('dex-easy-jonglage-10-minutes', 'catalog', 'DEX', 'easy', array['daily']::text[], 'Jonglage, 10 minutes', 'Le jonglage entraîne la coordination œil-main et la concentration.', 'Pendant 10 minutes, s’exercer à jongler avec trois balles, des foulards ou des chaussettes roulées.', array['Commence avec une seule balle, puis deux.', 'Lance à hauteur des yeux, sans bouger les pieds.']::text[], '{"type":"timer","minutes":10}'::jsonb, array['moins de 10 min']::text[], null, '[]'::jsonb, true),
('dex-easy-mobilite-epaules-et-hanches-5-minutes', 'catalog', 'DEX', 'easy', array['daily']::text[], 'Mobilité épaules et hanches, 5 minutes', 'Ces deux articulations limitent beaucoup de gestes : elles méritent un travail régulier.', 'Pendant 5 minutes, faire des rotations lentes et amples des épaules, des hanches, du bassin et du cou.', array['Fais des cercles larges et contrôlés.', 'Change de sens à mi-parcours.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['sans matériel', 'moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('dex-easy-corde-a-sauter-5-minutes', 'catalog', 'DEX', 'easy', array['daily']::text[], 'Corde à sauter, 5 minutes', 'Sauter à la corde améliore le rythme, la coordination et la légèreté des appuis.', 'Pendant 5 minutes, sauter à la corde (ou mimer le geste sans corde) en séries de 30 secondes.', array['Saute bas, sur la pointe des pieds.', 'Les poignets tournent, pas les bras.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('dex-easy-calcul-mental-rapide-5-minutes', 'catalog', 'DEX', 'easy', array['daily']::text[], 'Calcul mental rapide, 5 minutes', 'La vitesse de calcul mental entretient la vivacité d’esprit.', 'Pendant 5 minutes, résoudre des calculs mentaux sans calculatrice, en essayant d’aller plus vite à chaque série.', array['Commence par des additions, puis des multiplications.', 'Chronomètre une série de 10 calculs pour te mesurer.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], null, '[]'::jsonb, true),
('dex-easy-ecriture-de-la-main-faible-5-minutes', 'catalog', 'DEX', 'easy', array['daily']::text[], 'Écriture de la main faible, 5 minutes', 'Utiliser l’autre main bouscule les habitudes du cerveau et affine le geste.', 'Pendant 5 minutes, écrire ou dessiner de la main non dominante, en visant la lisibilité plus que la vitesse.', array['Écris des lignes de lettres simples.', 'Détends ton poignet.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['moins de 10 min']::text[], null, '[]'::jsonb, true),
('dex-easy-dactylographie-10-minutes', 'catalog', 'DEX', 'easy', array['daily']::text[], 'Dactylographie, 10 minutes', 'Taper vite et sans regarder le clavier fait gagner du temps chaque jour.', 'Pendant 10 minutes, s’entraîner à la dactylographie sur un exercice en ligne ou sur un texte recopié sans regarder le clavier.', array['Garde les doigts sur la rangée centrale.', 'Vise la précision avant la vitesse.']::text[], '{"type":"timer","minutes":10}'::jsonb, array['numérique']::text[], null, '[]'::jsonb, true),
('dex-easy-pas-de-coordination-5-minutes', 'catalog', 'DEX', 'easy', array['daily']::text[], 'Pas de coordination, 5 minutes', 'Coordonner bras et jambes dans un rythme demande au corps d’apprendre vite.', 'Pendant 5 minutes, enchaîner pas chassés, pas croisés et sauts latéraux en suivant un rythme régulier.', array['Compte les temps à voix haute.', 'Commence lentement et accélère peu à peu.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['sans matériel', 'moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('dex-easy-reflexes-contre-un-mur-5-minutes', 'catalog', 'DEX', 'easy', array['daily']::text[], 'Réflexes contre un mur, 5 minutes', 'Rattraper une balle améliore la vitesse de réaction et la précision.', 'Pendant 5 minutes, lancer une balle contre un mur et la rattraper, avec une main puis l’autre.', array['Éloigne-toi peu à peu du mur.', 'Passe à des rebonds imprévisibles quand tu es à l’aise.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['moins de 10 min']::text[], null, '[]'::jsonb, true),
('dex-easy-casse-tete-de-logique-10-minutes', 'catalog', 'DEX', 'easy', array['daily']::text[], 'Casse-tête de logique, 10 minutes', 'Résoudre un problème sous contrainte de temps rend l’esprit plus réactif.', 'Pendant 10 minutes, résoudre des casse-tête de logique : sudoku, grilles, énigmes ou puzzles.', array['Passe au suivant si tu bloques plus de deux minutes.', 'Note ton meilleur temps.']::text[], '{"type":"timer","minutes":10}'::jsonb, array['jeu']::text[], null, '[]'::jsonb, true),
('dex-easy-mobilite-du-dos-5-minutes', 'catalog', 'DEX', 'easy', array['daily']::text[], 'Mobilité du dos, 5 minutes', 'Un dos mobile facilite tous les mouvements du quotidien.', 'Pendant 5 minutes, enchaîner des exercices de mobilité du dos : chat-vache, rotations, bascule du bassin.', array['Bouge lentement avec la respiration.', 'Reste dans une amplitude confortable.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['sans matériel', 'moins de 10 min', 'sport']::text[], null, '[]'::jsonb, true),
('dex-easy-n-uds-et-origami-10-minutes', 'catalog', 'DEX', 'easy', array['daily']::text[], 'Nœuds et origami, 10 minutes', 'Les gestes fins entraînent la précision des doigts et la patience.', 'Pendant 10 minutes, apprendre ou pratiquer des nœuds, un origami ou un autre travail manuel fin.', array['Suis un tutoriel court au début.', 'Reprends le même pliage plusieurs fois pour aller plus vite.']::text[], '{"type":"timer","minutes":10}'::jsonb, array['moins de 10 min']::text[], null, '[]'::jsonb, true),
('dex-easy-danse-libre-10-minutes', 'catalog', 'DEX', 'easy', array['daily']::text[], 'Danse libre, 10 minutes', 'Bouger au rythme de la musique entraîne la coordination et l’expression corporelle.', 'Pendant 10 minutes, danser librement sur de la musique, en variant les mouvements et les rythmes.', array['Choisis une musique qui donne envie de bouger.', 'Teste des mouvements que tu n’as jamais faits.']::text[], '{"type":"timer","minutes":10}'::jsonb, array['sans matériel', 'sport']::text[], null, '[]'::jsonb, true),
('dex-medium-seance-de-souplesse-20-minutes', 'catalog', 'DEX', 'medium', array['daily', 'weekly']::text[], 'Séance de souplesse, 20 minutes', 'Une séance complète apporte des gains de souplesse plus durables que quelques étirements.', 'Pendant 20 minutes, faire une séance de souplesse en tenant chaque étirement 30 à 45 secondes, sur tout le corps.', array['Échauffe-toi 2 minutes avant.', 'Respire lentement et relâche un peu plus à chaque expiration.']::text[], '{"type":"timer","minutes":20}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('dex-medium-equilibre-et-proprioception-15-minutes', 'catalog', 'DEX', 'medium', array['daily', 'weekly']::text[], 'Équilibre et proprioception, 15 minutes', 'Travailler l’équilibre sollicite les petits muscles stabilisateurs des chevilles et des genoux.', 'Pendant 15 minutes, enchaîner des exercices d’équilibre : une jambe, yeux fermés, coussin instable, déplacements lents.', array['Prévois un appui proche pour te rattraper.', 'Augmente la difficulté progressivement.']::text[], '{"type":"timer","minutes":15}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('dex-medium-mobilite-60-minutes-dans-la-semaine', 'catalog', 'DEX', 'medium', array['weekly']::text[], 'Mobilité, 60 minutes dans la semaine', 'Quelques séances courtes de mobilité valent mieux qu’une longue séance isolée.', 'Cumuler 60 minutes de mobilité ou d’étirements sur la semaine, en plusieurs séances.', array['Quatre séances de 15 minutes conviennent.', 'Ajoute tes minutes après chaque séance.']::text[], '{"type":"counter","target":60,"unit":"minutes"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('dex-medium-jonglage-progressif-15-minutes', 'catalog', 'DEX', 'medium', array['daily']::text[], 'Jonglage progressif, 15 minutes', 'Passer à des figures plus complexes développe la coordination fine.', 'Pendant 15 minutes, s’entraîner à enchaîner des cascades de trois balles ou à apprendre une nouvelle figure de jonglage.', array['Compte le nombre de lancers sans chute et bats ton record.', 'Alterne séries courtes et pauses.']::text[], '{"type":"timer","minutes":15}'::jsonb, array['moins de 20 min']::text[], null, '[]'::jsonb, true),
('dex-medium-corde-a-sauter-15-minutes', 'catalog', 'DEX', 'medium', array['daily', 'weekly']::text[], 'Corde à sauter, 15 minutes', 'Le travail à la corde développe l’agilité des appuis et l’endurance.', 'Pendant 15 minutes, sauter à la corde en alternant pas simples, pieds joints et pas de course.', array['Alterne 1 minute d’effort et 30 secondes de repos.', 'Choisis un sol qui amortit.']::text[], '{"type":"timer","minutes":15}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('dex-medium-geste-precis-90-minutes-dans-la-semaine', 'catalog', 'DEX', 'medium', array['weekly']::text[], 'Geste précis, 90 minutes dans la semaine', 'La pratique régulière d’un geste précis (instrument, dessin, couture, modélisme) affine la dextérité manuelle.', 'Cumuler 90 minutes de pratique manuelle précise sur la semaine : instrument, dessin, couture, bricolage fin.', array['Des séances de 15 à 30 minutes suffisent.', 'Choisis une seule activité pour progresser.']::text[], '{"type":"counter","target":90,"unit":"minutes"}'::jsonb, array['bricolage']::text[], null, '[]'::jsonb, true),
('dex-medium-sport-de-reflexes-20-minutes', 'catalog', 'DEX', 'medium', array['daily', 'weekly']::text[], 'Sport de réflexes, 20 minutes', 'Les sports de raquette ou de balle entraînent la vitesse de réaction et le placement.', 'Pendant 20 minutes, pratiquer un jeu de réflexes : tennis de table, badminton, ballon, boxe contre une cible.', array['Joue avec un ami si possible.', 'Reste sur la pointe des pieds, prêt à repartir.']::text[], '{"type":"timer","minutes":20}'::jsonb, array['sport', 'extérieur']::text[], null, '[]'::jsonb, true),
('dex-medium-agilite-mentale-20-minutes', 'catalog', 'DEX', 'medium', array['daily']::text[], 'Agilité mentale, 20 minutes', 'Une série de problèmes variés entraîne le passage rapide d’une idée à l’autre.', 'Pendant 20 minutes, alterner logique, calcul mental, mots croisés et énigmes, en changeant de type d’exercice toutes les 5 minutes.', array['Change d’exercice même quand tu es lancé.', 'Note les types que tu fais le plus lentement.']::text[], '{"type":"timer","minutes":20}'::jsonb, array['jeu']::text[], null, '[]'::jsonb, true),
('dex-medium-yoga-ou-assouplissements-60-minutes', 'catalog', 'DEX', 'medium', array['weekly']::text[], 'Yoga ou assouplissements, 60 minutes', 'Le yoga combine souplesse, équilibre et concentration.', 'Cumuler 60 minutes de yoga ou d’assouplissements dirigés sur la semaine.', array['Une vidéo guidée aide à suivre le rythme.', 'Ne force jamais une posture.']::text[], '{"type":"counter","target":60,"unit":"minutes"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('dex-medium-parcours-d-agilite-20-minutes', 'catalog', 'DEX', 'medium', array['daily', 'weekly']::text[], 'Parcours d’agilité, 20 minutes', 'Slalomer, sauter et changer de direction entraîne les appuis et la vivacité.', 'Pendant 20 minutes, faire un parcours d’agilité : slalom entre des plots, sauts latéraux, échelle de rythme, changements de direction.', array['Marque le parcours avec des bouteilles ou des chaussures.', 'Chronomètre un tour et cherche à le battre.']::text[], '{"type":"timer","minutes":20}'::jsonb, array['sport', 'extérieur']::text[], null, '[]'::jsonb, true),
('dex-medium-activite-de-coordination-45-minutes', 'catalog', 'DEX', 'medium', array['weekly']::text[], 'Activité de coordination, 45 minutes', 'Découvrir un nouveau mouvement oblige le cerveau à s’adapter.', 'Cumuler 45 minutes sur une activité de coordination nouvelle pour toi : danse, escalade, arts martiaux, patin, slackline.', array['Choisis une activité accessible près de chez toi.', 'Fais-le même si tu te sens maladroit au début.']::text[], '{"type":"counter","target":45,"unit":"minutes"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('dex-medium-dactylographie-rapide-20-minutes', 'catalog', 'DEX', 'medium', array['daily', 'weekly']::text[], 'Dactylographie rapide, 20 minutes', 'La vitesse de frappe se gagne par séances courtes et régulières.', 'Pendant 20 minutes, s’exercer à la dactylographie avec des tests chronométrés et des exercices de précision.', array['Passe sur des textes longs pour tenir la cadence.', 'Corrige d’abord les erreurs récurrentes.']::text[], '{"type":"timer","minutes":20}'::jsonb, array['numérique']::text[], null, '[]'::jsonb, true),
('dex-high-souplesse-120-minutes-dans-la-semaine', 'catalog', 'DEX', 'high', array['weekly']::text[], 'Souplesse, 120 minutes dans la semaine', 'Deux heures de souplesse par semaine débloquent des amplitudes que les séances courtes ne donnent pas.', 'Cumuler 120 minutes de travail de souplesse sur la semaine : étirements, yoga, mobilité.', array['Prévois quatre séances de 30 minutes.', 'Reste à la limite de la gêne, pas de la douleur.']::text[], '{"type":"counter","target":120,"unit":"minutes"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('dex-high-coordination-90-minutes-dans-la-semaine', 'catalog', 'DEX', 'high', array['weekly']::text[], 'Coordination, 90 minutes dans la semaine', 'Un volume de pratique régulier en coordination change la façon de bouger.', 'Cumuler 90 minutes de coordination sur la semaine : danse, arts martiaux, escalade, sports de balle.', array['Alterne des séances techniques et des séances de jeu.', 'Note une chose améliorée à chaque séance.']::text[], '{"type":"counter","target":90,"unit":"minutes"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('dex-high-yoga-ou-assouplissements-45-minutes', 'catalog', 'DEX', 'high', array['daily', 'weekly']::text[], 'Yoga ou assouplissements, 45 minutes', 'Une séance longue permet d’aller jusqu’à des postures plus exigeantes.', 'Pendant 45 minutes, faire une séance complète de yoga ou d’assouplissements, avec échauffement et retour au calme.', array['Prépare un tapis et un espace dégagé.', 'Suis un cours en ligne pour ne pas t’arrêter.']::text[], '{"type":"timer","minutes":45}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('dex-high-habilete-manuelle-120-minutes', 'catalog', 'DEX', 'high', array['weekly']::text[], 'Habileté manuelle, 120 minutes', 'Deux heures de pratique manuelle par semaine donnent des progrès visibles en dextérité.', 'Cumuler 120 minutes de pratique manuelle précise sur la semaine : instrument, dessin, couture, maquette, jonglage.', array['Planifie des séances de 20 à 30 minutes.', 'Fixe un objectif simple pour la semaine.']::text[], '{"type":"counter","target":120,"unit":"minutes"}'::jsonb, array['bricolage']::text[], null, '[]'::jsonb, true),
('dex-high-jonglage-60-minutes-cumulees', 'catalog', 'DEX', 'high', array['weekly', 'monthly']::text[], 'Jonglage, 60 minutes cumulées', 'Une heure de jonglage cumulée suffit en général pour maîtriser la cascade de trois balles.', 'Cumuler 60 minutes de pratique du jonglage sur la période, jusqu’à enchaîner au moins 30 lancers.', array['Entraîne-toi par séances courtes.', 'Filme-toi pour repérer les fautes.']::text[], '{"type":"counter","target":60,"unit":"minutes"}'::jsonb, array['moins de 20 min']::text[], null, '[]'::jsonb, true),
('dex-high-agilite-mentale-90-minutes', 'catalog', 'DEX', 'high', array['weekly']::text[], 'Agilité mentale, 90 minutes', 'Jouer à des jeux de stratégie et de logique entraîne la vitesse de réflexion.', 'Cumuler 90 minutes de jeux d’agilité mentale sur la semaine : échecs, logique, calcul, jeux de réflexes.', array['Joue des parties rapides pour forcer la vitesse.', 'Analyse une partie perdue.']::text[], '{"type":"counter","target":90,"unit":"minutes"}'::jsonb, array['jeu']::text[], null, '[]'::jsonb, true),
('dex-high-mobilite-5-heures-dans-le-mois', 'catalog', 'DEX', 'high', array['monthly']::text[], 'Mobilité, 5 heures dans le mois', 'Cinq heures de mobilité par mois, c’est 10 minutes par jour, trois jours sur quatre.', 'Cumuler 5 heures de mobilité, d’étirements ou de yoga sur le mois.', array['Garde un créneau fixe chaque jour.', 'Ajoute tes minutes dans le compteur après chaque séance.']::text[], '{"type":"counter","target":300,"unit":"minutes"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('dex-high-pratique-manuelle-6-heures', 'catalog', 'DEX', 'high', array['monthly']::text[], 'Pratique manuelle, 6 heures', 'Six heures de pratique manuelle en un mois suffisent à apprendre un geste complexe.', 'Cumuler 6 heures de pratique d’un geste précis sur le mois : instrument, dessin, modélisme, couture, calligraphie.', array['Choisis une seule activité.', 'Note ta progression chaque semaine.']::text[], '{"type":"counter","target":360,"unit":"minutes"}'::jsonb, array['bricolage']::text[], null, '[]'::jsonb, true),
('dex-high-sport-de-coordination-6-heures', 'catalog', 'DEX', 'high', array['monthly']::text[], 'Sport de coordination, 6 heures', 'Un mois de pratique régulière transforme la coordination.', 'Cumuler 6 heures de sport de coordination sur le mois : escalade, danse, arts martiaux, sports de raquette.', array['Cherche un cours ou un club près de chez toi.', 'Mélange séances techniques et séances ludiques.']::text[], '{"type":"counter","target":360,"unit":"minutes"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('dex-expert-souplesse-10-heures-dans-le-mois', 'catalog', 'DEX', 'expert', array['monthly']::text[], 'Souplesse, 10 heures dans le mois', 'Dix heures de souplesse par mois, c’est une vraie transformation du corps.', 'Cumuler 10 heures de souplesse, de yoga et de mobilité sur le mois. Adapte à ta condition et ne force jamais une articulation.', array['Planifie des séances courtes presque chaque jour.', 'Mesure ta souplesse au départ (toucher les pieds) et à la fin.']::text[], '{"type":"counter","target":600,"unit":"minutes"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('dex-expert-geste-maitrise-20-heures', 'catalog', 'DEX', 'expert', array['monthly', 'epic']::text[], 'Geste maîtrisé, 20 heures', 'Vingt heures suffisent pour acquérir un geste précis dans une nouvelle pratique.', 'Cumuler 20 heures de pratique d’un geste manuel précis : instrument, dessin, couture, calligraphie, jonglage, lancer.', array['Choisis un objectif visible (un morceau, un dessin, une figure).', 'Garde une trace de chaque séance.']::text[], '{"type":"counter","target":1200,"unit":"minutes"}'::jsonb, array['bricolage']::text[], null, '[]'::jsonb, true),
('dex-expert-agilite-totale-4-heures', 'catalog', 'DEX', 'expert', array['weekly', 'monthly']::text[], 'Agilité totale, 4 heures', 'Souplesse, réflexes, équilibre et coordination : toutes les formes d’agilité en quatre heures.', 'Cumuler 4 heures de pratique d’agilité variée : souplesse, équilibre, coordination et réflexes. Adapte à ta condition.', array['Répartis en séances de 30 à 45 minutes.', 'Change de type d’exercice à chaque séance.']::text[], '{"type":"counter","target":240,"unit":"minutes"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('dex-expert-activite-de-coordination-30-heures', 'catalog', 'DEX', 'expert', array['monthly', 'epic']::text[], 'Activité de coordination, 30 heures', 'Trente heures suffisent pour passer d’un débutant maladroit à un pratiquant à l’aise.', 'Cumuler 30 heures de pratique d’une activité de coordination : danse, escalade, arts martiaux, sports de raquette. Adapte à ta condition.', array['Inscris-toi à un cours pour progresser plus vite.', 'Fixe-toi un petit objectif de démonstration.']::text[], '{"type":"counter","target":1800,"unit":"minutes"}'::jsonb, array['sport']::text[], null, '[]'::jsonb, true),
('dex-expert-agilite-mentale-12-heures', 'catalog', 'DEX', 'expert', array['monthly']::text[], 'Agilité mentale, 12 heures', 'Douze heures de stratégie et de logique dans le mois forment un esprit vif et rapide.', 'Cumuler 12 heures de jeux de stratégie, de logique ou de calcul sur le mois : échecs, go, énigmes, calcul mental.', array['Joue contre quelqu’un de plus fort que toi.', 'Reviens sur tes erreurs après chaque partie.']::text[], '{"type":"counter","target":720,"unit":"minutes"}'::jsonb, array['jeu']::text[], null, '[]'::jsonb, true),
('con-easy-marche-15-minutes', 'catalog', 'CON', 'easy', array['daily']::text[], 'Marche, 15 minutes', 'Marcher un quart d’heure par jour est le geste de santé le plus simple et le plus efficace.', 'Marcher 15 minutes d’affilée, dehors si possible, à un rythme soutenu.', array['Un peu d’air, sans écran.', 'Tu peux les répartir en deux sorties de 8 minutes.']::text[], '{"type":"timer","minutes":15}'::jsonb, array['extérieur', 'sport']::text[], null, '[]'::jsonb, true),
('con-easy-coucher-avant-23-heures', 'catalog', 'CON', 'easy', array['daily']::text[], 'Coucher avant 23 heures', 'Se coucher tôt allonge le sommeil et améliore l’énergie du lendemain.', 'Être couché, lumière éteinte, avant 23 heures ce soir.', array['Prépare tes affaires du lendemain avant 22 h.', 'Mets une alarme de rappel une heure avant.']::text[], '{"type":"simple"}'::jsonb, array['sommeil']::text[], null, '[]'::jsonb, true),
('con-easy-ecrans-coupes-30-minutes-avant-dormir', 'catalog', 'CON', 'easy', array['daily']::text[], 'Écrans coupés 30 minutes avant dormir', 'La lumière bleue retarde l’endormissement : une demi-heure sans écran aide à s’endormir.', 'Éteindre tous les écrans (téléphone, télévision, ordinateur) 30 minutes avant de dormir.', array['Prépare une lecture ou une musique douce.', 'Mets le téléphone à charger hors de la chambre.']::text[], '{"type":"simple"}'::jsonb, array['sommeil', 'détox']::text[], null, '[]'::jsonb, true),
('con-easy-petit-dejeuner-dans-l-heure-du-reveil', 'catalog', 'CON', 'easy', array['daily']::text[], 'Petit-déjeuner dans l’heure du réveil', 'Un vrai petit-déjeuner stabilise l’énergie jusqu’au déjeuner.', 'Prendre un vrai petit-déjeuner (protéines et fruit) dans l’heure qui suit le réveil.', array['Œufs, yaourt, fromage blanc, pain complet.', 'Prépare-le la veille si tu manques de temps.']::text[], '{"type":"simple"}'::jsonb, array['alimentation', 'matin']::text[], null, '[]'::jsonb, true),
('con-easy-marche-apres-le-repas-10-minutes', 'catalog', 'CON', 'easy', array['daily']::text[], 'Marche après le repas, 10 minutes', 'Dix minutes de marche après manger facilitent la digestion et stabilisent la glycémie.', 'Marcher 10 minutes juste après le déjeuner ou le dîner, à un rythme tranquille.', array['Dehors de préférence.', 'Commence dans les 20 minutes après le repas.']::text[], '{"type":"timer","minutes":10}'::jsonb, array['extérieur', 'moins de 10 min']::text[], null, '[]'::jsonb, true),
('con-easy-lumiere-du-jour-10-minutes', 'catalog', 'CON', 'easy', array['daily']::text[], 'Lumière du jour, 10 minutes', 'La lumière du matin cale l’horloge interne et améliore le sommeil du soir.', 'Passer 10 minutes dehors à la lumière du jour avant midi.', array['Un café en terrasse ou un tour du pâté de maisons suffit.', 'Même sous les nuages, la lumière extérieure compte.']::text[], '{"type":"timer","minutes":10}'::jsonb, array['extérieur', 'matin']::text[], null, '[]'::jsonb, true),
('con-easy-repos-sans-ecran-10-minutes', 'catalog', 'CON', 'easy', array['daily']::text[], 'Repos sans écran, 10 minutes', 'Une courte pause aide le corps à récupérer entre deux efforts.', 'S’allonger ou s’asseoir 10 minutes, yeux fermés ou regard au loin, sans téléphone.', array['Mets un minuteur.', 'Respire lentement par le nez.']::text[], '{"type":"timer","minutes":10}'::jsonb, array['moins de 10 min', 'détox']::text[], null, '[]'::jsonb, true),
