('g-danse-salsa-t1', 'catalog', 'DEX', 'easy', array['daily']::text[], 'Salsa, 20 minutes guidées', 'La salsa travaille le rythme, les appuis et le plaisir de danser à deux.', 'Pendant 20 minutes, danser la salsa (pas de base, tours et déplacements), en suivant un cours guidé (vidéo, application ou professeur).', array['Déroulé conseillé : 3 minutes d’échauffement, pas de base, puis enchaînement de figures et retour au calme.', 'Garde les genoux souples et compte les temps à voix haute.']::text[], '{"type":"timer","minutes":20}'::jsonb, array['guidé', 'danse', 'sport']::text[], 'danse', '[{"ability":"CHA","pct":30},{"ability":"FOR","pct":10}]'::jsonb, true),
('g-danse-salsa-t2', 'catalog', 'DEX', 'medium', array['weekly']::text[], 'Salsa, 90 min cette semaine', 'La salsa travaille le rythme, les appuis et le plaisir de danser à deux. Quelques séances par semaine donnent des progrès visibles.', 'Cumuler 90 minutes sur la semaine : danser la salsa (pas de base, tours et déplacements), en suivant des séances guidées.', array['Garde les genoux souples et compte les temps à voix haute.', 'Répartis tes séances sur 2 à 4 jours et ajoute les minutes après chaque séance.']::text[], '{"type":"counter","target":90,"unit":"minutes"}'::jsonb, array['guidé', 'danse', 'sport']::text[], 'danse', '[{"ability":"CHA","pct":30},{"ability":"FOR","pct":10}]'::jsonb, true),
('g-danse-salsa-t3', 'catalog', 'DEX', 'high', array['monthly']::text[], 'Salsa, 6 heures ce mois-ci', 'La salsa travaille le rythme, les appuis et le plaisir de danser à deux. Un mois de pratique régulière installe l’habitude et le niveau.', 'Cumuler 6 heures sur le mois : danser la salsa (pas de base, tours et déplacements), avec un cours ou un programme guidé.', array['Garde les genoux souples et compte les temps à voix haute.', 'Planifie tes créneaux à l’avance et note ta progression chaque semaine.']::text[], '{"type":"counter","target":360,"unit":"minutes"}'::jsonb, array['guidé', 'danse', 'sport']::text[], 'danse', '[{"ability":"CHA","pct":30},{"ability":"FOR","pct":10}]'::jsonb, true),
('g-danse-salsa-t4', 'catalog', 'DEX', 'expert', array['epic']::text[], 'Salsa, 25 heures de pratique', 'La salsa travaille le rythme, les appuis et le plaisir de danser à deux. Un grand objectif, qui demande de la constance sur la durée.', 'Cumuler 25 heures de pratique guidée (danser la salsa (pas de base, tours et déplacements)) jusqu’à enchaîner une chorégraphie de 3 minutes sans t’arrêter. Adapte à ta condition et consulte un professionnel au besoin.', array['Garde les genoux souples et compte les temps à voix haute.', 'Fixe-toi un point d’étape toutes les deux semaines pour mesurer ta progression.']::text[], '{"type":"counter","target":1500,"unit":"minutes"}'::jsonb, array['guidé', 'danse', 'sport']::text[], 'danse', '[{"ability":"CHA","pct":30},{"ability":"FOR","pct":10}]'::jsonb, true),
('g-danse-hip-hop-t1', 'catalog', 'DEX', 'easy', array['daily']::text[], 'Hip-hop, 20 minutes guidées', 'Le hip-hop développe la coordination et l’expression personnelle.', 'Pendant 20 minutes, danser le hip-hop (isolations, grooves et enchaînements), en suivant un cours guidé (vidéo, application ou professeur).', array['Déroulé conseillé : échauffement des articulations, grooves de base, apprentissage d’un enchaînement de 8 temps.', 'Travaille d’abord le rythme du buste, puis ajoute les bras.']::text[], '{"type":"timer","minutes":20}'::jsonb, array['guidé', 'danse', 'sport']::text[], 'danse', '[{"ability":"CHA","pct":30},{"ability":"FOR","pct":10}]'::jsonb, true),
