('g-danse-danse-contemporaine-t1', 'catalog', 'DEX', 'easy', array['daily']::text[], 'Danse contemporaine, 20 minutes guidées', 'Cette danse libère le mouvement et travaille l’équilibre et la souplesse.', 'Pendant 20 minutes, pratiquer la danse contemporaine (travail au sol, élan et fluidité), en suivant un cours guidé (vidéo, application ou professeur).', array['Déroulé conseillé : échauffement au sol, déplacements dans l’espace, improvisation guidée.', 'Respire dans chaque mouvement et ne cherche pas la vitesse.']::text[], '{"type":"timer","minutes":20}'::jsonb, array['guidé', 'danse', 'sport']::text[], 'danse', '[{"ability":"CHA","pct":30},{"ability":"FOR","pct":10}]'::jsonb, true),
